package cn.adc.shared.config;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ClinicDirectoryProviderTest {
 static SourceStamp stamp(){return new SourceStamp("SYNTHETIC-source","test-v1","test-reviewer",Instant.parse("2026-11-05T00:00:00Z"),true);}
 static ReferenceDataReader reader(){return new ReferenceDataReader(){public Optional<Clinic> clinic(long id){return id==1?Optional.of(new Clinic(1,"SYNTHETIC-clinic")):Optional.empty();}public Optional<Dentist> dentist(long id){return id==7?Optional.of(new Dentist(7,"SYNTHETIC-qualification-text")):Optional.empty();}};}
 @Test void explicitZoneMatchesExistingClinicWithoutWriting(){var a=new ClinicConfigurationAdapter(reader(),()->List.of(new ClinicConfigurationAdapter.Entry(1,"SYNTHETIC-clinic","Europe/Berlin",stamp())));assertEquals("Europe/Berlin",a.find(1).zone().getId());assertThrows(ConfigurationUnavailable.class,()->a.find(2));}
 @Test void missingDuplicateInvalidAndMismatchedSourcesFailClosed(){assertThrows(ConfigurationUnavailable.class,()->new ClinicConfigurationAdapter(reader(),List::of).find(1));for(String zone:List.of("","Mars/None","+08:00"))assertThrows(ConfigurationUnavailable.class,()->new ClinicConfigurationAdapter(reader(),()->List.of(new ClinicConfigurationAdapter.Entry(1,"SYNTHETIC-clinic",zone,stamp()))).find(1));var e=new ClinicConfigurationAdapter.Entry(1,"SYNTHETIC-clinic","Asia/Tokyo",stamp());assertThrows(ConfigurationUnavailable.class,()->new ClinicConfigurationAdapter(reader(),()->List.of(e,e)).find(1));assertThrows(ConfigurationUnavailable.class,()->new ClinicConfigurationAdapter(reader(),()->List.of(new ClinicConfigurationAdapter.Entry(1,"wrong","Asia/Tokyo",stamp()))).find(1));}
 @Test void withdrawnSourceIsNotCachedAndUnavailabilityIsNotDefaulted(){var entries=new java.util.concurrent.atomic.AtomicReference<>(List.of(new ClinicConfigurationAdapter.Entry(1,"SYNTHETIC-clinic","UTC",stamp())));var a=new ClinicConfigurationAdapter(reader(),entries::get);assertEquals("UTC",a.find(1).zone().getId());entries.set(List.of());assertThrows(ConfigurationUnavailable.class,()->a.find(1));assertThrows(ConfigurationUnavailable.class,()->new ClinicConfigurationAdapter(reader(),()->{throw new IllegalStateException("source unavailable");}).find(1));}
}
